+                keyValue -> new DslErrorInfo(
+                    keyValue.getKey(),
+                    keyValue.getValue().firstOccurrenceTimestamp(),
+                    keyValue.getValue().retryCount()
+                )
+            )
+            .collect(Collectors.toList());
